package net.officefloor.hq.app.plan;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPlan {
    public void respond(@Val Plan plan, SheetRepository sheets, ObjectResponse<PlanResponse> response) {
        response.send(PlanResponse.of(plan, sheets.today(plan.sheetId())));
    }
}
package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.history.ViewAsOf;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPlans {
    public void respond(@Val SheetResponse sheet, @Val ViewAsOf asOf, SheetHistory history,
            ObjectResponse<List<PlanResponse>> response) {
        response.send(history.view(sheet.id(), asOf.on(), jdbc -> {
            LocalDate today = new SheetRepository(jdbc).today(sheet.id());
            return new PlanRepository(jdbc).list(sheet.id()).stream().map(p -> PlanResponse.of(p, today)).toList();
        }));
    }
}
package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import java.util.List;

/** A plan: its person, amount (two decimals), start, every N days or a day of the month (the other null), end, how
 *  many claims it has made so far and its next dates after the sheet's today (see Plan#nextDates). */
public record PlanResponse(long id, long personId, String amount, String start, Integer every, Integer day, String end,
        int generated, List<String> nextDates) {

    static PlanResponse of(Plan p, LocalDate today) {
        return new PlanResponse(p.id(), p.personId(), p.amount().toPlainString(), p.start().toString(), p.every(), p.day(),
                p.end().toString(), p.generated(), p.nextDates(today).stream().map(LocalDate::toString).toList());
    }
}

